def countSumQuadruples(nums):
    n = len(nums)
    diff = {}
    ans = 0
    for b in range(n - 3, 0, -1):
        c = b + 1
        nc = nums[c]
        for d in range(c + 1, n):
            v = nums[d] - nc
            diff[v] = diff.get(v, 0) + 1
        nb = nums[b]
        for a in range(b):
            ans += diff.get(nums[a] + nb, 0)
    return ans % 1000000007
